4	/// Reads and writes the saved session (issue #46) — the file behind `SessionSnapshot`.
5	///
6	/// **Every operation is best-effort.** The app must behave identically with the file absent, empty,
7	/// unreadable, or corrupt: a session that fails to load is a launch with no restore, never an error
8	/// the user sees. Failures log and are swallowed.
9	///
10	/// The URL is injectable so unit tests point at a temp directory — which also keeps the whole
11	/// feature clear of `Defaults`, and therefore clear of the single-writer rule parallel test workers
12	/// impose on a shared UserDefaults domain (`SharedPrefDefaultsTests`).
13	final class SessionStore {
14	  /// Where the file lives, **scoped by bundle id**.
15	  ///
16	  /// The scoping is mandatory, not tidiness: `GhosttyApp` already writes into
17	  /// `Application Support/Workroom/` from all three identities (Workroom, Workroom Dev, Workroom
18	  /// Nightly), so an unscoped path would let a Dev run's fixture temp-dir workrooms be restored into
19	  /// the release build. UserDefaults gets that separation free from the bundle id; a file has to buy
20	  /// it back.
21	  static func defaultURL(
22	    bundleID: String? = Bundle.main.bundleIdentifier,
23	    fileManager: FileManager = .default
24	  ) -> URL {
25	    let root = fileManager.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
26	      .appendingPathComponent("Workroom", isDirectory: true)
27	      .appendingPathComponent(bundleID ?? "com.developwithstyle.workroom", isDirectory: true)
28	    return root.appendingPathComponent("session.json")
29	  }
30	
31	  /// The store production and the UI tests should use.
32	  ///
33	  /// In fixture mode this is a **no-op unless a test names a file**. The path is bundle-id scoped, so
34	  /// a fixture launch would otherwise write over the developer's own `Workroom Dev` session — and the
35	  /// fixture's temp-directory workrooms would then be restored into a real launch.
36	  static func forCurrentEnvironment() -> SessionStore {
37	    guard UITestFixture.isActive else { return SessionStore() }
38	    guard let path = UITestFixture.sessionFilePath else {
39	      return SessionStore(url: SessionStore.defaultURL(), isDisabled: true)
40	    }
41	    return SessionStore(url: URL(fileURLWithPath: path))
42	  }
43	
44	  let url: URL
45	  /// A disabled store reads nothing and writes nothing — fixture mode without a named session file.
46	  private let isDisabled: Bool
47	  /// Where an undecodable file is moved once, so a bug report has something to attach instead of the
48	  /// evidence being deleted.
49	  var quarantineURL: URL {
50	    url.deletingLastPathComponent().appendingPathComponent("session.corrupt.json")
51	  }
52	
53	  /// True once a file written by a NEWER schema has been read. Every write is then refused for the
54	  /// rest of the run — otherwise this build silently destroys a session it could not understand, and
55	  /// three build identities ship side by side, so that rollback is a real path rather than a
56	  /// hypothetical one.
57	  private(set) var writesDisabled = false
58	
59	  private let fileManager: FileManager
60	  private let logger = Logger(
61	    subsystem: "com.developwithstyle.workroom", category: "session")
62	  /// Encoding and the write happen here so neither runs on the main actor; only the capture does.
63	  private let queue = DispatchQueue(
64	    label: "com.developwithstyle.workroom.session", qos: .utility)
65	
66	  init(
67	    url: URL = SessionStore.defaultURL(), fileManager: FileManager = .default,
68	    isDisabled: Bool = false
69	  ) {
70	    self.url = url
71	    self.fileManager = fileManager
72	    self.isDisabled = isDisabled
73	  }
74	
75	  // MARK: Read
76	
77	  enum ReadOutcome: Equatable {
78	    /// Nothing usable — a fresh install, an unreadable file, or one this build cannot decode. The
79	    /// caller falls back to its cold-start path.
80	    case none
81	    case restored(SessionFile, SessionSanitizeReport)
82	    /// Written by a newer build: restore nothing, and `writesDisabled` is now true.
83	    case newerSchema
84	
85	    static func == (lhs: ReadOutcome, rhs: ReadOutcome) -> Bool {
86	      switch (lhs, rhs) {
87	      case (.none, .none), (.newerSchema, .newerSchema): return true
88	      case (.restored(let lf, let lr), .restored(let rf, let rr)):
89	        return lf.windows == rf.windows && lf.schemaVersion == rf.schemaVersion && lr == rr
90	      default: return false
91	      }
92	    }
93	  }
94	
95	  func read() -> ReadOutcome {
96	    guard !isDisabled, fileManager.fileExists(atPath: url.path) else { return .none }
97	
98	    // Refused BEFORE decoding: the element caps in `SessionLimits` bound how many things a file
99	    // describes, not how many bytes one of them spends.
100	    if let size = try? fileManager.attributesOfItem(atPath: url.path)[.size] as? Int,
101	      size > SessionLimits.maxFileBytes
102	    {
103	      logger.error("session file is \(size) bytes, over the limit — quarantining")
104	      quarantine()
105	      return .none
106	    }
107	
108	    guard let data = try? Data(contentsOf: url) else {
109	      logger.error("session file unreadable")
110	      return .none
111	    }
112	    guard !data.isEmpty else { return .none }
113	
114	    let decoder = JSONDecoder()
115	    decoder.dateDecodingStrategy = .iso8601
116	    guard let file = try? decoder.decode(SessionFile.self, from: data) else {
117	      logger.error("session file could not be decoded — quarantining")
118	      quarantine()
119	      return .none
120	    }
121	
122	    switch file.compatibility {
123	    case .newer:
124	      let message =
125	        "session file schema \(file.schemaVersion) is newer than "
126	        + "\(SessionFile.currentSchemaVersion) — not restoring, writes disabled for this run"
127	      logger.notice("\(message, privacy: .public)")
128	      writesDisabled = true
129	      return .newerSchema
130	    case .unreadable:
131	      logger.notice("session file schema \(file.schemaVersion) has no migration — discarding")
132	      return .none
133	    case .current:
134	      break
135	    }
136	
137	    let (sanitized, report) = file.sanitized()
138	    if !report.isEmpty {
139	      logger.notice("session file dropped entries — \(report.summary, privacy: .public)")
140	    }
141	    // A file whose windows all dropped is not a session. Saying so lets the caller take its
142	    // cold-start fallback instead of launching emptier than deleting the file would have.
143	    guard !sanitized.windows.isEmpty else { return .none }
144	    return .restored(sanitized, report)
145	  }
146	
147	  // MARK: Write
148	
149	  /// Persist off the main actor. Coalescing is the caller's job (see `AppStore+Session`).
150	  func write(_ file: SessionFile) {
151	    guard !isDisabled, !writesDisabled else { return }
152	    queue.async { [weak self] in self?.persist(file) }
153	  }
154	
155	  /// Persist before returning — the quit path, where the process may not survive long enough for an
156	  /// async write to land.
157	  func writeSynchronously(_ file: SessionFile) {
158	    guard !isDisabled, !writesDisabled else { return }
159	    queue.sync { self.persist(file) }
160	  }
161	
162	  func clear() {
163	    guard !isDisabled else { return }
164	    queue.sync { try? self.fileManager.removeItem(at: self.url) }
165	  }
166	
167	  // MARK: Scrollback sidecars (issue #144)
168	
169	  /// One plain-text file per pane, beside `session.json`. Deliberately NOT inside it: that document
170	  /// is rewritten on every coalesced save, and a few hundred KB of terminal output per pane has no
171	  /// business riding along with the layout.
172	  var scrollbackDirectory: URL {
173	    url.deletingLastPathComponent().appendingPathComponent("scrollback", isDirectory: true)
174	  }
175	
176	  private func scrollbackURL(forTabKey key: String) -> URL {
177	    // The key is a `TabSession.key` UUID string: filesystem-safe and unique within a snapshot, so
178	    // no escaping and no collision handling.
179	    scrollbackDirectory.appendingPathComponent("\(key).txt")
180	  }
181	
182	  func writeScrollback(_ text: String, forTabKey key: String) {
183	    guard !isDisabled, !writesDisabled, !text.isEmpty else { return }
184	    do {
185	      try fileManager.createDirectory(at: scrollbackDirectory, withIntermediateDirectories: true)
186	      try Data(text.utf8).write(to: scrollbackURL(forTabKey: key), options: .atomic)
187	    } catch {
188	      // Best-effort like everything else here: a pane with no sidecar simply restores empty.
189	      logger.error("scrollback write failed: \(error.localizedDescription)")
190	    }
191	  }
192	
193	  /// The saved text for a pane, or nil when there is none, it is unreadable, or it fails validation.
194	  ///
195	  /// A file that fails validation is **deleted**: it would fail identically on every future launch,
196	  /// and unlike `session.json` a scrollback sidecar has no diagnostic value worth quarantining.
197	  func readScrollback(forTabKey key: String) -> String? {
198	    guard !isDisabled else { return nil }
199	    let fileURL = scrollbackURL(forTabKey: key)
200	    guard fileManager.fileExists(atPath: fileURL.path) else { return nil }
201	
202	    if let size = try? fileManager.attributesOfItem(atPath: fileURL.path)[.size] as? Int,
203	      size > SessionLimits.maxScrollbackFileBytes
204	    {
205	      logger.notice("scrollback sidecar is \(size) bytes, over the limit — discarding")
206	      try? fileManager.removeItem(at: fileURL)
207	      return nil
208	    }
209	    guard let data = try? Data(contentsOf: fileURL) else { return nil }
210	    guard let text = String(data: data, encoding: .utf8) else {
211	      logger.notice("scrollback sidecar is not valid UTF-8 — discarding")
212	      try? fileManager.removeItem(at: fileURL)
213	      return nil
214	    }
215	    let cleaned = Self.strippingControlBytes(text)
216	    return cleaned.isEmpty ? nil : cleaned
217	  }
218	
219	  /// Drop sidecars for panes that are no longer in the session.
220	  ///
221	  /// Runs once after the write pass, unconditionally — including when every write failed. A pane
222	  /// whose capture is now empty wrote no sidecar, so its old one is removed here and yesterday's
223	  /// output cannot reappear under today's empty pane.
224	  func pruneScrollback(keeping keys: Set<String>) {
225	    guard !isDisabled else { return }
226	    guard
227	      let entries = try? fileManager.contentsOfDirectory(
228	        at: scrollbackDirectory, includingPropertiesForKeys: nil)
229	    else { return }
230	    for entry in entries where entry.pathExtension == "txt" {
231	      let key = entry.deletingPathExtension().lastPathComponent
232	      if !keys.contains(key) { try? fileManager.removeItem(at: entry) }
233	    }
234	  }
235	
236	  /// Remove C0 control bytes except newline, carriage return and tab.
237	  ///
238	  /// The captured text is rendered output, never raw PTY bytes, so it carries no escape sequences to
239	  /// begin with. This exists so a hand-edited sidecar cannot inject one and leave the parser
240	  /// mid-sequence on replay. CR is kept: the divider is CRLF.
241	  nonisolated static func strippingControlBytes(_ text: String) -> String {
242	    String(
243	      text.unicodeScalars.filter { scalar in
244	        scalar == "\n" || scalar == "\r" || scalar == "\t" || scalar.value >= 0x20
245	      })
246	  }
247	
248	  private func persist(_ file: SessionFile) {
249	    let encoder = JSONEncoder()
250	    encoder.dateEncodingStrategy = .iso8601
251	    // Readable and diff-stable on purpose: "delete this file and relaunch" is a support instruction
252	    // a user can follow, and the file is something a bug report can usefully attach.
253	    encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
254	
255	    guard let data = try? encoder.encode(file) else {
256	      logger.error("session snapshot could not be encoded")
257	      return
258	    }
259	    do {
260	      // `Data.write(.atomic)` does NOT create intermediate directories, and the bundle-id
261	      // subdirectory does not exist on a first run — without this every write fails silently.
262	      try fileManager.createDirectory(
263	        at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
264	      // Atomic: a reader sees the complete old document or the complete new one, never a partial
265	      // write from a process that died mid-save.
266	      try data.write(to: url, options: .atomic)
267	    } catch {
268	      logger.error("session snapshot could not be written: \(error.localizedDescription)")
269	    }
270	  }
271	
272	  /// Move a file this build cannot read aside — once. A prior quarantine is replaced rather than
273	  /// accumulating; the newest failure is the useful one.
274	  private func quarantine() {
275	    try? fileManager.removeItem(at: quarantineURL)
276	    do {
277	      try fileManager.moveItem(at: url, to: quarantineURL)
278	    } catch {
279	      // If it cannot even be moved, delete it — leaving it in place would fail the same way on
280	      // every launch forever.
281	      try? fileManager.removeItem(at: url)
282	    }
283	  }
284	}
