import AppKit
import Foundation

/// What one window contributes to the saved session (issue #46). `SessionCoordinator` decides when
/// this runs; `SessionStore` owns the file.
///
/// Capture reads only through existing public queries plus the one new
/// `TerminalSessions.sessionCapture(forTargetID:)`, so the four pane dictionaries stay
/// `@Published private` where they belong.
extension AppStore {
  /// This window's whole restorable state, right now.
  ///
  /// Runs on the main actor and must stay cheap: it is called on every coalesced save, and (via the
  /// ceiling) at a steady cadence while terminals are busy. It walks a few dozen small values and
  /// allocates no views — the expensive part, encoding, happens off the main actor in `SessionStore`.
  func captureWindowSession() -> WindowSession {
    WindowSession(
      windowKey: sessionKey.uuidString,
      frame: hostWindow.map { NSStringFromRect($0.frame) },
      isKey: hostWindow?.isKeyWindow ?? false,
      selectedTargetID: Self.targetIDString(for: selectedTargetID),
      targets: captureTargetSessions(),
      workroomSplits: captureWorkroomSplits(),
      expandedTargets: expandedTerminalTargets.isEmpty
        ? nil : expandedTerminalTargets.sorted())
  }

  /// Every target that currently owns panes, in a stable order so an unchanged layout produces an
  /// unchanged document — which is what lets the coordinator's equality gate drop the write.
  private func captureTargetSessions() -> [TargetSession] {
    terminals.activeTargetIDs.sorted().compactMap { targetID in
      guard let captured = terminals.sessionCapture(forTargetID: targetID) else { return nil }

      // Tabs the bridge refuses (today: run tabs) drop out here, and the split leaf that pointed at
      // one collapses with them — `LayoutNode.capture` applies the same rule `PaneLayout.removingLeaf`
      // does, so a split can never be left addressing a pane that was not written.
      var keysByTabID: [TerminalTab.ID: String] = [:]
      var tabs: [TabSession] = []
      for tab in captured.tabs {
        let key = tab.id.uuidString
        guard let session = TabSession(key: key, tab: tab) else { continue }
        keysByTabID[tab.id] = key
        tabs.append(session)
      }
      guard !tabs.isEmpty else { return nil }

      let split = captured.split.flatMap { layout in
        LayoutNode<String>.capture(layout) { keysByTabID[$0] }
      }
      return TargetSession(
        targetID: targetID, tabs: tabs, split: split,
        focusedKey: captured.focused.flatMap { keysByTabID[$0] },
        terminalCounter: captured.counter)
    }
  }

  /// The workroom-into-workroom split groups, with `SidebarID` leaves reduced to the same target-id
  /// strings `Defaults[.sidebarSelection]` and `workroomTabOrder` already persist — so no new id
  /// format ships, and `AppStore.sidebarID(forTargetID:in:)` resolves them back (dropping any that
  /// no longer exist).
  private func captureWorkroomSplits() -> [LayoutNode<String>] {
    workroomSplits.compactMap { layout in
      LayoutNode<String>.capture(layout) { Self.targetIDString(for: $0) }
    }
  }

  /// Write every live pane's scrollback to its sidecar (issue #144). Quit only — reading each
  /// pane's history is far too heavy for a coalesced save.
  ///
  /// The tab key must match what `captureTargetSessions` wrote for the same tab, or the sidecar
  /// belongs to nothing and is pruned the moment it is written.
  func captureScrollback(into store: SessionStore) {
    for targetID in terminals.activeTargetIDs {
      guard let captured = terminals.sessionCapture(forTargetID: targetID) else { continue }
      for tab in captured.tabs {
        // Run tabs are not persisted at all, so their output must not be either.
        guard tab.surface?.isRunCommandSurface != true else { continue }
        guard let text = tab.surface?.captureScrollback() else { continue }
        store.writeScrollback(text, forTabKey: tab.id.uuidString)
      }
    }
  }

  /// Tell the coordinator this window changed. Every dirty source funnels through here so there is
  /// one place to look when asking "what causes a save?".
  func markSessionDirty() {
    SessionCoordinator.shared.markDirty()
  }

  // MARK: Restore

  /// Adopt this window's saved session, once. Called from `attachWindow` — see the comment there for
  /// why not from the view initialiser.
  func claimSessionIfNeeded() {
    guard !didClaimSession else { return }
    didClaimSession = true
    // Every ⌘N window opens blank, matching how the persisted selection already behaves.
    guard claimsSavedSession else { return }
    guard
      let claimed = projectStore.claimSession(for: sessionKey, isLaunchWindow: isRestoreWindow)
    else { return }
    pendingSessionRestore = claimed
    // Keep the window's identity stable across launches: it now owns this session's slot.
    if let key = UUID(uuidString: claimed.windowKey) { sessionKey = key }
    // The session owns selection; `Defaults[.sidebarSelection]` (already loaded into
    // `pendingRestoreSelection`) stays as the cold-start fallback for a launch with no session file.
    // Feeding the session's value through the SAME field means `apply` needs no second branch.
    if let selected = claimed.selectedTargetID { pendingRestoreSelection = selected }
  }

  /// Rehydrate the claimed session at the end of `apply(_:)`. One-shot: `apply` runs twice per
  /// bootstrap (`load("none")` then `load("fast")`), and reloads come through it too.
  func restorePersistedSessionIfPending(in projects: [Project]) {
    guard let session = pendingSessionRestore else { return }
    pendingSessionRestore = nil
    defer { projectStore.finishSessionRestore() }

    var restoredTargetIDs: Set<TerminalTarget.ID> = []
    for saved in session.targets {
      // A target that no longer resolves — its workroom was deleted between launches — is dropped
      // whole, the same self-heal `validatedSelection` and `pruneWorkroomSplitToLiveLeaves` apply.
      guard let sid = Self.sidebarID(forTargetID: saved.targetID, in: projects),
        let target = target(for: sid)
      else { continue }
      let coordinator = projectStore.sessionCoordinator
      guard
        terminals.restore(saved, for: target, scrollback: { coordinator.scrollback(forTabKey: $0) })
          > 0
      else { continue }
      restoredTargetIDs.insert(target.id)
    }

    // The workroom-into-workroom split groups (issue #23). A leaf whose workroom is gone collapses,
    // and a group left with fewer than two leaves dissolves — `materialize` enforces that, so a
    // one-workroom "group" can never reach the live model.
    workroomSplits = session.workroomSplits.compactMap { saved in
      saved.materialize { Self.sidebarID(forTargetID: $0, in: projects) }
    }
    // Sidebar terminal-subtree expansion (issue #30). Only for targets that actually came back —
    // an expand flag pointing at nothing would render an empty disclosure.
    expandedTerminalTargets = Set(session.expandedTargets ?? []).intersection(restoredTargetIDs)

    refreshSelectionHasTabs()
  }
}

    return false
  }
  return split.contains(focused)
}

/// The tab ids currently on screen: the split's members when the split is visible, else the focused
/// solo tab. Drives occlusion.
func visibleTabIDs(for target: TerminalTarget) -> [TerminalTab.ID] {
  if isSplitVisible(for: target), let split = splitByTarget[target.id] { return split.tabIDs }
  if let focused = focusedTab(for: target) { return [focused.id] }
  return []
}

// MARK: Lifecycle

/// Create the target's first terminal the first time its pane appears. Once opened, an emptied tab
/// set is left as-is (the user closed them on purpose).
func ensureTab(for target: TerminalTarget) {
  if orderByTarget[target.id] == nil { addTab(for: target) }
}

// MARK: Session restore (issue #46)

/// Re-materialise a target's panes from a saved session.
///
/// The only path that sets the four per-target dictionaries wholesale, so it lives here beside the
/// mutation primitives rather than in `AppStore`. Three deliberate properties:
///
/// - **Tabs get FRESH ids.** A `TerminalTab.ID` is unique across *windows* at runtime and OS
///   notification clicks are routed by it (`WindowRegistry.ownerOf(tabID:)`), so reviving persisted
///   ids would put a duplicate-id hazard one bug away for no benefit. The persisted keys are a join
///   key valid only within one snapshot; order, split and focus are rewired through them here.
/// - **Focus is set with `notify: false`** (the escape `reap` uses): a restore is not a navigation,
///   and firing `onFocusChange` would seed back/forward with a place the user never went.
/// - **No-op when the target already has tabs**, so a restore can never race or duplicate a live
///   session.
///
/// Terminals come back as fresh login shells — libghostty has no session dump — but in their
/// remembered directory, which is the half that matters. Nothing spawns here: constructing a
/// surface is inert until it enters a window.
@discardableResult
func restore(
  _ session: TargetSession, for target: TerminalTarget,
  scrollback: (String) -> String? = { _ in nil }
) -> Int {
  guard (tabsByTarget[target.id] ?? [:]).isEmpty else { return 0 }

  var idsByKey: [String: TerminalTab.ID] = [:]
  var order: [TerminalTab.ID] = []
  var tabs: [TerminalTab.ID: TerminalTab] = [:]
  var restoredTerminals = 0

  for saved in session.tabs {
    let tab: TerminalTab
    if saved.kind == TabSession.terminalKind, let payload = saved.terminal {
      // `command:` is deliberately never passed: run tabs are not persisted, and this makes even a
      // hand-edited file unable to start a process on launch.
      tab = makeTerminalTab(
        for: target,
        cwd: Self.restoredCwd(payload.cwd, fallback: target.path),
        title: payload.defaultTitle,
        restoredScrollback: scrollback(saved.key))
      restoredTerminals += 1
    } else if let content = saved.restoredContent {
      tab = TerminalTab(
        content: content, diffViewModeOverride: saved.restoredDiffViewMode,
        markdownPreviewOverride: saved.restoredMarkdownPreview)
    } else {
      continue
    }
    idsByKey[saved.key] = tab.id
    order.append(tab.id)
    tabs[tab.id] = tab
  }

  guard !order.isEmpty else { return 0 }

  tabsByTarget[target.id] = tabs
  orderByTarget[target.id] = order
  splitByTarget[target.id] = session.split.flatMap { saved in
    saved.materialize { idsByKey[$0] }
  }
  setFocused(
    session.focusedKey.flatMap { idsByKey[$0] } ?? order.first, for: target.id, notify: false)
  // `makeTerminalTab` bumps the counter per terminal it builds, so take whichever is higher: the
  // saved value keeps "Terminal 7" from becoming "Terminal 3" again after closes.
  counts[target.id] = max(session.terminalCounter ?? 0, counts[target.id] ?? 0)
  reconcileOcclusion(for: target)
  return order.count
}

/// The directory a restored terminal should open in: the remembered one while it is still a live
/// directory, else the target's own path. libghostty cannot spawn into a directory that no longer
/// exists, so an unchecked value would turn a deleted folder into a dead pane.
///
/// Pure and `nonisolated` so it is unit-testable without a session, a target, or a surface.
nonisolated static func restoredCwd(_ cwd: String?, fallback: String) -> String {
  guard let cwd, !cwd.isEmpty else { return fallback }
  var isDirectory: ObjCBool = false
  guard FileManager.default.fileExists(atPath: cwd, isDirectory: &isDirectory),
    isDirectory.boolValue
  else { return fallback }
  return cwd
}

/// Open a new solo terminal at the end of the strip and focus it (⌘T). Does not touch the split.
@discardableResult
func addTab(for target: TerminalTarget) -> TerminalTab {
  let tab = makeTerminalTab(for: target, cwd: target.path)
  insert(tab, for: target)
  setFocused(tab.id, for: target.id)
  reconcileOcclusion(for: target)
  return tab
}

// MARK: Content tabs (issue #66)
//
//   single-click file ─▶ openDiffPreview ─┬─ persisted tab for this file+rev exists → focus it (Inv C)
//                                          ├─ a preview tab exists → retarget IN PLACE, same id (Inv B)
//                                          └─ else → new preview tab           (≤1 preview/target: Inv A)

  var order = orderByTarget[target.id] ?? []
  order.removeAll { $0 == id }
  if let i = order.firstIndex(of: other) {
    order.insert(id, at: i + 1)
  } else {
    order.append(id)
  }
  orderByTarget[target.id] = order
}

private func makeTerminalTab(
  for target: TerminalTarget, cwd: String, command: String? = nil, title: String? = nil,
  restoredScrollback: String? = nil
) -> TerminalTab {
  let count = (counts[target.id] ?? 0) + 1
  counts[target.id] = count
  let view = makeView(target, cwd, command)
  view.adoptRestoredScrollback(restoredScrollback)
  let tab = TerminalTab.terminal(view: view, defaultTitle: title ?? "Terminal \(count)")

  let targetID = target.id
  let tabID = tab.id
  view.onActivity = { [weak self] activity in
    self?.activityHandler?(targetID, tabID, activity)
  }
  view.onTitleChange = { [weak self] title in
    self?.updateTitle(title, forTab: tabID, target: targetID)
  }
  view.onCwdChange = { [weak self] cwd in
    self?.updateCwd(cwd, forTab: tabID, target: targetID)
  }
  view.onCommandFinished = { [weak self] exitCode in
    // Exit code feeds the inline-agent manager (issue #49); the title-clear path (issue #2)
    // ignores it.
    self?.handleCommandFinished(forTab: tabID, target: targetID, exitCode: exitCode)
  }
  view.onProgressReport = { [weak self] active in
    self?.updateProgress(active, forTab: tabID, target: targetID)
  }
